  3080  /* kex_method_list
  3081   * Generate formatted preference list in buf
  3082   */
  3083  static size_t
  3084  kex_method_list(unsigned char *buf, size_t list_strlen,
  3085                  LIBSSH2_COMMON_METHOD ** method)
  3086  {
  3087      _libssh2_htonu32(buf, list_strlen);
  3088      buf += 4;
  3089
  3090      if(!method || !*method) {
  3091          return 4;
  3092      }
  3093
  3094      while(*method && (*method)->name) {
  3095          int mlen = strlen((*method)->name);
  3096          memcpy(buf, (*method)->name, mlen);
  3097          buf += mlen;
  3098          *(buf++) = ',';
  3099          method++;
  3100      }
  3101
  3102      return list_strlen + 4;
  3103  }
