   677          session->socket_block_directions |= LIBSSH2_SESSION_BLOCK_OUTBOUND;
   678          return LIBSSH2_ERROR_EAGAIN;
   679      }
   680
   681      p->osent += rc;         /* we sent away this much data */
   682
   683      return rc < length ? LIBSSH2_ERROR_EAGAIN : LIBSSH2_ERROR_NONE;
   684  }
