  3323  static const LIBSSH2_COMMON_METHOD *
  3324  kex_get_method_by_name(const char *name, size_t name_len,
  3325                         const LIBSSH2_COMMON_METHOD ** methodlist)
  3326  {
  3327      while(*methodlist) {
  3328          if((strlen((*methodlist)->name) == name_len) &&
  3329              (strncmp((*methodlist)->name, name, name_len) == 0)) {
  3330              return *methodlist;
  3331          }
  3332          methodlist++;
  3333      }
  3334      return NULL;
  3335  }
