  3418   */
  3419  static int kex_agree_kex_hostkey(LIBSSH2_SESSION * session, unsigned char *kex,
  3420                                   unsigned long kex_len, unsigned char *hostkey,
  3421                                   unsigned long hostkey_len)
  3422  {
  3423      const LIBSSH2_KEX_METHOD **kexp = libssh2_kex_methods;
  3424      unsigned char *s;
