  3426      if(session->kex_prefs) {
  3427          s = (unsigned char *) session->kex_prefs;
  3428
  3429          while(s && *s) {
  3430              unsigned char *q, *p = (unsigned char *) strchr((char *) s, ',');
  3431              size_t method_len = (p ? (size_t)(p - s) : strlen((char *) s));
  3432              q = kex_agree_instr(kex, kex_len, s, method_len);
  3433              if(q) {
  3434                  const LIBSSH2_KEX_METHOD *method = (const LIBSSH2_KEX_METHOD *)
  3435                      kex_get_method_by_name((char *) s, method_len,
  3436                                             (const LIBSSH2_COMMON_METHOD **)
  3437                                             kexp);
  3438
  3439                  if(!method) {
  3440                      /* Invalid method -- Should never be reached */
  3441                      return -1;
  3442                  }
  3443
  3444                  /* We've agreed on a key exchange method,
  3445                   * Can we agree on a hostkey that works with this kex?
  3446                   */
  3447                  if(kex_agree_hostkey(session, method->flags, hostkey,
  3448                                        hostkey_len) == 0) {
  3449                      session->kex = method;
  3450                      if(session->burn_optimistic_kexinit && (kex == q)) {
  3451                          /* Server sent an optimistic packet, and client agrees
  3452                           * with preference cancel burning the first KEX_INIT
  3453                           * packet that comes in */
  3454                          session->burn_optimistic_kexinit = 0;
  3455                      }
  3456                      return 0;
  3457                  }
  3458              }
  3459
  3460              s = p ? p + 1 : NULL;
  3461          }
  3462          return -1;
  3463      }
  3464
  3465      while(*kexp && (*kexp)->name) {
  3466          s = kex_agree_instr(kex, kex_len,
  3467                              (unsigned char *) (*kexp)->name,
  3468                              strlen((*kexp)->name));
  3469          if(s) {
  3470              /* We've agreed on a key exchange method,
  3471               * Can we agree on a hostkey that works with this kex?
  3472               */
  3473              if(kex_agree_hostkey(session, (*kexp)->flags, hostkey,
  3474                                    hostkey_len) == 0) {
  3475                  session->kex = *kexp;
  3476                  if(session->burn_optimistic_kexinit && (kex == s)) {
  3477                      /* Server sent an optimistic packet, and client agrees
  3478                       * with preference cancel burning the first KEX_INIT
  3479                       * packet that comes in */
  3480                      session->burn_optimistic_kexinit = 0;
  3481                  }
  3482                  return 0;
  3483              }
  3484          }
  3485          kexp++;
  3486      }
  3487      return -1;
  3488  }
