  3658
  3659  /* kex_agree_methods
  3660   * Decide which specific method to use of the methods offered by each party
  3661   */
  3662  static int kex_agree_methods(LIBSSH2_SESSION * session, unsigned char *data,
  3663                               unsigned data_len)
  3664  {
  3665      unsigned char *kex, *hostkey, *crypt_cs, *crypt_sc, *comp_cs, *comp_sc,
  3666          *mac_cs, *mac_sc;
  3667      size_t kex_len, hostkey_len, crypt_cs_len, crypt_sc_len, comp_cs_len;
  3668      size_t comp_sc_len, mac_cs_len, mac_sc_len;
  3669      struct string_buf buf;
  3670
  3671      if(data_len < 17)
  3672          return -1;
  3673
  3674      buf.data = (unsigned char *)data;
  3675      buf.len = data_len;
  3676      buf.dataptr = buf.data;
  3677      buf.dataptr++; /* advance past packet type */
  3678
  3679      /* Skip cookie, don't worry, it's preserved in the kexinit field */
  3680      buf.dataptr += 16;
  3681
  3682      /* Locate each string */
  3683      if(_libssh2_get_string(&buf, &kex, &kex_len))
  3684          return -1;
  3685      if(_libssh2_get_string(&buf, &hostkey, &hostkey_len))
  3686          return -1;
  3687      if(_libssh2_get_string(&buf, &crypt_cs, &crypt_cs_len))
  3688          return -1;
  3689      if(_libssh2_get_string(&buf, &crypt_sc, &crypt_sc_len))
  3690          return -1;
  3691      if(_libssh2_get_string(&buf, &mac_cs, &mac_cs_len))
  3692          return -1;
  3693      if(_libssh2_get_string(&buf, &mac_sc, &mac_sc_len))
  3694          return -1;
  3695      if(_libssh2_get_string(&buf, &comp_cs, &comp_cs_len))
  3696          return -1;
  3697      if(_libssh2_get_string(&buf, &comp_sc, &comp_sc_len))
  3698          return -1;
  3699
  3700      /* If the server sent an optimistic packet, assume that it guessed wrong.
  3701       * If the guess is determined to be right (by kex_agree_kex_hostkey)
  3702       * This flag will be reset to zero so that it's not ignored */
  3703      if(_libssh2_check_length(&buf, 1)) {
  3704          session->burn_optimistic_kexinit = *(buf.dataptr++);
  3705      }
  3706      else {
  3707          return -1;
  3708      }
  3709
  3710      /* Next uint32 in packet is all zeros (reserved) */
  3711
  3712      if(kex_agree_kex_hostkey(session, kex, kex_len, hostkey, hostkey_len)) {
  3713          return -1;
  3714      }
  3715
  3716      if(kex_agree_crypt(session, &session->local, crypt_cs, crypt_cs_len)
  3717         || kex_agree_crypt(session, &session->remote, crypt_sc,
  3718                            crypt_sc_len)) {
  3719          return -1;
  3720      }
  3721
  3722      if(kex_agree_mac(session, &session->local, mac_cs, mac_cs_len) ||
  3723          kex_agree_mac(session, &session->remote, mac_sc, mac_sc_len)) {
  3724          return -1;
  3725      }
  3726
  3727      if(kex_agree_comp(session, &session->local, comp_cs, comp_cs_len) ||
  3728          kex_agree_comp(session, &session->remote, comp_sc, comp_sc_len)) {
  3729          return -1;
  3730      }
  3731
  3732  #if 0
  3733      if(libssh2_kex_agree_lang(session, &session->local, lang_cs, lang_cs_len)
  3734          || libssh2_kex_agree_lang(session, &session->remote, lang_sc,
  3735                                    lang_sc_len)) {
  3736          return -1;
  3737      }
  3738  #endif
  3739
  3740      _libssh2_debug(session, LIBSSH2_TRACE_KEX, "Agreed on KEX method: %s",
   300      "3des-cbc",
   301      "DEK-Info: DES-EDE3-CBC",
   302      8,                          /* blocksize */
